xpath.script:

(function () {
    function postJSON(url, payload) {
        return fetch(url, {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify(payload)
        })
        .then(r => r.json())
        // unwrap JSON-RPC envelopes from Odoo: {result: {...}}
        .then(data => (data && typeof data === 'object' && 'result' in data) ? data.result : data);
    }

    const isFr = (document.documentElement.getAttribute('lang') || '').startsWith('fr');

    // ---------------------------
    // RENTAL DATES (if present)
    // ---------------------------
    (function setupRental() {
        const wrap = document.getElementById('rental-dates');
        if (!wrap) return;

        const orderId = wrap.getAttribute('data-order-id');
        const token   = wrap.getAttribute('data-access-token') || '';

        const startEl = document.getElementById('rental_start_date');
        const returnEl = document.getElementById('rental_return_date');
        const applyBtn = document.getElementById('apply_rental_dates');

        const labelIdle   = isFr ? 'Appliquer les dates' : 'Apply dates';
        const labelBusy   = isFr ? 'Enregistrement…'     : 'Saving…';

        function setBusy(busy) {
            if (!applyBtn) return;
            applyBtn.disabled = busy;
            applyBtn.textContent = busy ? labelBusy : labelIdle;
        }

        function isValidRange(a, b) {
            if (!a || !b) return false;
            return a <= b; // YYYY-MM-DD strings compare lexicographically
        }

        async function applyDates() {
            const start_date  = startEl?.value || null;
            const return_date = returnEl?.value || null;

            if (!isValidRange(start_date, return_date)) {
                alert(isFr
                    ? 'Veuillez sélectionner une date de début et une date de retour, avec la date de retour le même jour ou après la date de début.'
                    : 'Please select a start date and a return date, with the return date on or after the start date.');
                return;
            }

            setBusy(true);
            try {
                const payload = { start_date, return_date };
                if (token) payload.access_token = token;

                const res = await postJSON(`/my/orders/${orderId}/set_rental_dates`, payload);

                if (res && res.ok) {
                    window.location.reload();
                } else {
                    console.error('Rental date update failed', res);
                    alert(isFr ? "Impossible d'enregistrer les dates de location. Veuillez réessayer."
                            : 'Could not save rental dates. Please try again.');
                }
            } catch (e) {
                console.error('Rental date update error', e);
                alert(isFr ? 'Erreur réseau lors de la sauvegarde des dates. Veuillez réessayer.'
                        : 'Network error while saving dates. Please try again.');
            } finally {
                setBusy(false);
            }
        }

        applyBtn && applyBtn.addEventListener('click', applyDates);
    })();

    // ---------------------------
    // PO NUMBER (if present)
    // ---------------------------
    (function setupPO() {
        const poWrap = document.getElementById('po-section'); // container div for PO field
        if (!poWrap) return;

        const orderId = poWrap.getAttribute('data-order-id');
        const token   = poWrap.getAttribute('data-access-token') || '';

        const poInput = document.getElementById('customer_po_number');
        const poBtn   = document.getElementById('apply_customer_po_number');

        const labelIdle = isFr ? 'Enregistrer' : 'Save';
        const labelBusy = isFr ? 'Enregistrement…' : 'Saving…';

        function setPoBusy(b) {
            if (!poBtn) return;
            poBtn.disabled = b;
            poBtn.textContent = b ? labelBusy : labelIdle;
        }

        async function applyPO() {
            setPoBusy(true);
            try {
                const payload = { customer_po_number: (poInput?.value || '').trim() };
                if (token) payload.access_token = token;

                const res = await postJSON(`/my/orders/${orderId}/set_customer_po_number`, payload);

                if (res && res.ok) {
                    window.location.reload();
                } else {
                    console.error('PO number update failed', res);
                    alert(isFr ? "Impossible d'enregistrer le numéro de bon de commande."
                            : 'Could not save the PO number.');
                }
            } catch (e) {
                console.error('PO number update error', e);
                alert(isFr ? "Erreur réseau lors de l'enregistrement."
                        : 'Network error while saving.');
            } finally {
                setPoBusy(false);
            }
        }

        poBtn && poBtn.addEventListener('click', applyPO);
    })();

})();

div.script:
document.addEventListener('DOMContentLoaded', function () {
    const approveBtn = document.querySelector('.flash-button');

    if (approveBtn) {
        approveBtn.addEventListener('click', function () {

            // approveBtn.setAttribute('approve-action', 'open_app');
            // console.log("approve-action updated to open_app");

            window.kwipped_approve.embedded_app.app_reference.clear_items();
        });
    }
});

window.kwipped_approve.add_listener = setInterval(function(){
    if(window.kwipped_approve && window.kwipped_approve.embedded_app && window.kwipped_approve.embedded_app.app_reference){
        clearInterval(window.kwipped_approve.add_listener);
        //Add listener here.
        window.kwipped_approve.embedded_app.app_reference.add_listener(function(message){
            if(message.action=="app_submitted"){
            console.log("This is a submitted application:",message.data);

            const orderId = document.querySelector('#approve_order_id')?.getAttribute('data-order-id');
            if (!orderId) {
                console.error("Order ID not found for APPROVE submission.");
                return;
            }

            fetch(`/approve/application_submitted/${orderId}`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify(message.data)
            })
            .then(res => res.json())
            .then(data => console.log("Approve submission logged:", data))
            .catch(err => console.error("Approve logging failed:", err));
            }
        });

    }
},100);
